        logic target_allows_nonsec_ar;
        logic category_match_ar;
        
        // Write channel security check
        always @(*) begin
            aw_violation[i] = 1'b0;
            aw_block[i] = 1'b0;
            
            if (m_awvalid[i]) begin
                // Check AxPROT[1] bit: 0=secure, 1=non-secure
                is_secure_transaction_aw = !m_awprot[i][1];
                target_is_secure_aw = slave_is_secure[aw_slave_sel[i]];
                target_allows_nonsec_aw = slave_allows_nonsec[aw_slave_sel[i]];
                
                // Firewall category check
                category_match_aw = (master_fw_cat_reg[i] == slave_fw_cat_reg[aw_slave_sel[i]]);
                
                // Security violation conditions:
                // 1. Non-secure master trying to access secure slave
                // 2. Non-secure transaction to secure-only slave
                // 3. Firewall category mismatch
                if (!master_is_secure[i] && target_is_secure_aw && !target_allows_nonsec_aw) begin
                    aw_violation[i] = 1'b1;
                    aw_block[i] = 1'b1;
                end else if (!is_secure_transaction_aw && target_is_secure_aw && !target_allows_nonsec_aw) begin
                    aw_violation[i] = 1'b1;
                    aw_block[i] = 1'b1;
                end else if (!category_match_aw && (master_fw_cat_reg[i] != 4'd1 || slave_fw_cat_reg[aw_slave_sel[i]] != 4'd1)) begin
                    // Category mismatch violation (except for default category 1)
                    aw_violation[i] = 1'b1;
                    aw_block[i] = 1'b1;
                end
            end
        end
        
        // Read channel security check
        always @(*) begin
            ar_violation[i] = 1'b0;
            ar_block[i] = 1'b0;
            
            if (m_arvalid[i]) begin
                // Check AxPROT[1] bit: 0=secure, 1=non-secure
                is_secure_transaction_ar = !m_arprot[i][1];
                target_is_secure_ar = slave_is_secure[ar_slave_sel[i]];
                target_allows_nonsec_ar = slave_allows_nonsec[ar_slave_sel[i]];
                
                // Firewall category check
                category_match_ar = (master_fw_cat_reg[i] == slave_fw_cat_reg[ar_slave_sel[i]]);
                
                // Security violation conditions:
                // 1. Non-secure master trying to access secure slave
                // 2. Non-secure transaction to secure-only slave  
                // 3. Firewall category mismatch
                if (!master_is_secure[i] && target_is_secure_ar && !target_allows_nonsec_ar) begin
                    ar_violation[i] = 1'b1;
                    ar_block[i] = 1'b1;
                end else if (!is_secure_transaction_ar && target_is_secure_ar && !target_allows_nonsec_ar) begin
                    ar_violation[i] = 1'b1;
                    ar_block[i] = 1'b1;
                end else if (!category_match_ar && (master_fw_cat_reg[i] != 4'd1 || slave_fw_cat_reg[ar_slave_sel[i]] != 4'd1)) begin
                    // Category mismatch violation (except for default category 1)
                    ar_violation[i] = 1'b1;
                    ar_block[i] = 1'b1;
                end
            end
        end
    end
endgenerate

// Global security alert
always @(*) begin
    security_alert = |aw_violation | |ar_violation;
end

// Violation logging
reg [31:0] violation_count;
reg [ID_WIDTH-1:0] last_violation_id;
reg [ADDR_WIDTH-1:0] last_violation_addr;
reg last_violation_is_write;

always @(posedge aclk or negedge aresetn) begin
    if (!aresetn) begin
        violation_count <= 32'd0;
        last_violation_id <= {7{1'b0}};
        last_violation_addr <= {32{1'b0}};
        last_violation_is_write <= 1'b0;
    end else begin
        // Log violations
        for (integer j = 0; j < NUM_MASTERS; j = j + 1) begin
            if (aw_violation[j]) begin
                violation_count <= violation_count + 1;
                last_violation_id <= m_awid[j];
                last_violation_addr <= m_awaddr[j];
                last_violation_is_write <= 1'b1;
            end else if (ar_violation[j]) begin
                violation_count <= violation_count + 1;
                last_violation_id <= m_arid[j];
                last_violation_addr <= m_araddr[j];
                last_violation_is_write <= 1'b0;
            end
        end
    end
end

// Address range based security (optional enhanced feature)
// Define secure address regions
localparam SECURE_REGION_START = 32'h8000_0000;
localparam SECURE_REGION_END   = 32'h9000_0000;

// Enhanced security check with address regions
generate
    for (i = 0; i < NUM_MASTERS; i = i + 1) begin : addr_range_check
        wire aw_in_secure_region = (m_awaddr[i] >= SECURE_REGION_START) && 
                                   (m_awaddr[i] < SECURE_REGION_END);
        wire ar_in_secure_region = (m_araddr[i] >= SECURE_REGION_START) && 
                                   (m_araddr[i] < SECURE_REGION_END);
        
        // Additional blocking based on address regions
        always @(*) begin
            if (aw_in_secure_region && !master_is_secure[i]) begin
                aw_block[i] = 1'b1;
            end
            if (ar_in_secure_region && !master_is_secure[i]) begin
                ar_block[i] = 1'b1;
            end
        end
    end
endgenerate

endmodule

